# Node.jsでPostgreSQLのコネクションプーリング設定

## 必要なパッケージのインストール

```bash
npm install pg
# または
npm install pg pg-pool
```

---

## 方法1: `pg-pool`を使った基本的なセットアップ

### 設定ファイルの作成 (`src/db/pool.js`)

```javascript
const { Pool } = require('pg');

// プール設定
const pool = new Pool({
  host:     process.env.DB_HOST     || 'localhost',
  port:     process.env.DB_PORT     || 5432,
  database: process.env.DB_NAME     || 'mydb',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD || 'password',

  // プーリング設定
  max:             10,   // 最大コネクション数（デフォルト: 10）
  min:              2,   // 最小コネクション数
  idleTimeoutMillis:    30000,  // アイドル接続のタイムアウト（30秒）
  connectionTimeoutMillis: 2000, // 接続取得のタイムアウト（2秒）
  maxUses:        7500,  // 1接続あたりの最大使用回数
});

// 接続エラーのハンドリング
pool.on('error', (err, client) => {
  console.error('プールの予期しないエラー:', err);
  process.exit(-1);
});

// 接続確認
pool.on('connect', (client) => {
  console.log('新しいクライアントがプールに接続しました');
});

pool.on('acquire', (client) => {
  console.log('クライアントをプールから取得しました');
});

pool.on('remove', (client) => {
  console.log('クライアントがプールから削除されました');
});

module.exports = pool;
```

---

## 方法2: クラスベースのラッパー実装

```javascript
// src/db/database.js
const { Pool } = require('pg');

class Database {
  constructor() {
    this.pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      ssl: process.env.NODE_ENV === 'production'
        ? { rejectUnauthorized: false }
        : false,
      max: 20,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });
  }

  // 単純なクエリ実行
  async query(text, params) {
    const start = Date.now();
    try {
      const result = await this.pool.query(text, params);
      const duration = Date.now() - start;
      console.log('クエリ実行:', { text, duration, rows: result.rowCount });
      return result;
    } catch (error) {
      console.error('クエリエラー:', error);
      throw error;
    }
  }

  // トランザクション用にクライアントを取得
  async getClient() {
    const client = await this.pool.connect();
    const originalQuery = client.query.bind(client);
    const originalRelease = client.release.bind(client);

    // タイムアウト付きでリリースを監視
    const releaseTimer = setTimeout(() => {
      console.error('クライアントが10秒以上チェックアウトされています！');
    }, 10000);

    client.query = (...args) => {
      client.lastQuery = args;
      return originalQuery(...args);
    };

    client.release = (err) => {
      clearTimeout(releaseTimer);
      client.query = originalQuery;
      client.release = originalRelease;
      return originalRelease(err);
    };

    return client;
  }

  // トランザクション処理のヘルパー
  async transaction(callback) {
    const client = await this.getClient();
    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  // プールの状態確認
  getPoolStatus() {
    return {
      total:   this.pool.totalCount,   // 全コネクション数
      idle:    this.pool.idleCount,    // アイドル数
      waiting: this.pool.waitingCount, // 待機中のリクエスト数
    };
  }

  // プールを閉じる
  async close() {
    await this.pool.end();
    console.log('データベースプールを閉じました');
  }
}

// シングルトンとしてエクスポート
module.exports = new Database();
```

---

## 使用例

### 基本的なCRUD操作

```javascript
// src/repositories/userRepository.js
const db = require('../db/database');

class UserRepository {
  // 全ユーザー取得
  async findAll() {
    const { rows } = await db.query(
      'SELECT * FROM users ORDER BY created_at DESC'
    );
    return rows;
  }

  // IDでユーザー取得
  async findById(id) {
    const { rows } = await db.query(
      'SELECT * FROM users WHERE id = $1',
      [id]
    );
    return rows[0] || null;
  }

  // ユーザー作成
  async create(userData) {
    const { name, email, age } = userData;
    const { rows } = await db.query(
      `INSERT INTO users (name, email, age, created_at)
       VALUES ($1, $2, $3, NOW())
       RETURNING *`,
      [name, email, age]
    );
    return rows[0];
  }

  // ユーザー更新
  async update(id, userData) {
    const { name, email } = userData;
    const { rows } = await db.query(
      `UPDATE users
       SET name = $1, email = $2, updated_at = NOW()
       WHERE id = $3
       RETURNING *`,
      [name, email, id]
    );
    return rows[0] || null;
  }

  // ユーザー削除
  async delete(id) {
    const { rowCount } = await db.query(
      'DELETE FROM users WHERE id = $1',
      [id]
    );
    return rowCount > 0;
  }
}

module.exports = new UserRepository();
```

### トランザクションの使用例

```javascript
// src/services/transferService.js
const db = require('../db/database');

async function transferMoney(fromId, toId, amount) {
  return await db.transaction(async (client) => {
    // 送金元の残高確認
    const { rows: [sender] } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
      [fromId]
    );

    if (!sender || sender.balance < amount) {
      throw new Error('残高不足です');
    }

    // 送金元から引き落とし
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    // 送金先へ入金
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    // 履歴記録
    const { rows: [transfer] } = await client.query(
      `INSERT INTO transfers (from_id, to_id, amount, created_at)
       VALUES ($1, $2, $3, NOW()) RETURNING *`,
      [fromId, toId, amount]
    );

    return transfer;
  });
}

module.exports = { transferMoney };
```

