  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 20,          // 最大コネクション数
  idleTimeoutMillis: 30000,   // アイドル接続を閉じるまでの時間
  connectionTimeoutMillis: 2000, // 接続取得のタイムアウト
});

module.exports = pool;
```

### クエリ実行

```javascript
const pool = require('./db');

// シンプルなクエリ（プールから自動取得・返却）
async function getUsers() {
  const result = await pool.query('SELECT * FROM users WHERE active = $1', [true]);
  return result.rows;
}

// トランザクション（手動でクライアント取得）
async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect(); // クライアント手動取得
  try {
    await client.query('BEGIN');
    await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
    await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // 必ず返却
  }
}
```

### エラーハンドリング

```javascript
// アイドル中のコネクションエラーを捕捉
pool.on('error', (err, client) => {
  console.error('予期せぬエラー:', err);
  process.exit(-1);
});
```

### 終了処理

```javascript
// アプリ終了時にプールを閉じる
process.on('SIGINT', async () => {
  await pool.end();
  process.exit(0);
});
```

---

### `max` の目安

| 用途 | 推奨値 |
|------|--------|
| 開発環境 | 5〜10 |
| 本番（小〜中） | 10〜20 |
| 本番（大） | 20〜50 |

PostgreSQL側の `max_connections`（デフォルト100）超えないよう注意。複数Nodeプロセス動くなら `max × プロセス数 < max_connections` になるよう調整。

