# コールバック地獄を async/await にリファクタリング

## Before: コールバック地獄 😱

```javascript
// ユーザー情報を取得 → 注文情報を取得 → 商品情報を取得する例

function getUserData(userId, callback) {
  setTimeout(() => {
    console.log('ユーザー取得完了');
    callback(null, { id: userId, name: '田中太郎' });
  }, 1000);
}

function getOrders(userId, callback) {
  setTimeout(() => {
    console.log('注文取得完了');
    callback(null, [{ orderId: 1, productId: 101 }]);
  }, 1000);
}

function getProduct(productId, callback) {
  setTimeout(() => {
    console.log('商品取得完了');
    callback(null, { id: productId, name: 'ノートPC', price: 80000 });
  }, 1000);
}

// 😱 コールバック地獄
getUserData(1, (err, user) => {
  if (err) {
    console.error('ユーザー取得エラー:', err);
    return;
  }

  getOrders(user.id, (err, orders) => {
    if (err) {
      console.error('注文取得エラー:', err);
      return;
    }

    getProduct(orders[0].productId, (err, product) => {
      if (err) {
        console.error('商品取得エラー:', err);
        return;
      }

      // ✅ ようやくデータが揃った
      console.log(`${user.name}さんの注文商品: ${product.name} (¥${product.price})`);
    });
  });
});
```

---

## After: async/await で解決 ✨

### Step 1: コールバック関数を Promise に変換

```javascript
// コールバック関数を Promise でラップ
function getUserData(userId) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      console.log('ユーザー取得完了');
      resolve({ id: userId, name: '田中太郎' });
    }, 1000);
  });
}

function getOrders(userId) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      console.log('注文取得完了');
      resolve([{ orderId: 1, productId: 101 }]);
    }, 1000);
  });
}

function getProduct(productId) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      console.log('商品取得完了');
      resolve({ id: productId, name: 'ノートPC', price: 80000 });
    }, 1000);
  });
}
```

### Step 2: async/await で書き直す

```javascript
// ✅ スッキリ！同期処理のように読める
async function fetchUserOrderDetails(userId) {
  try {
    const user    = await getUserData(userId);
    const orders  = await getOrders(user.id);
    const product = await getProduct(orders[0].productId);

    console.log(`${user.name}さんの注文商品: ${product.name} (¥${product.price})`);
    return { user, orders, product };

  } catch (err) {
    // エラーハンドリングを一箇所にまとめられる ✅
    console.error('データ取得エラー:', err);
    throw err;
  }
}

fetchUserOrderDetails(1);
```

---

## 応用: 並列処理で高速化 ⚡

```javascript
// ❌ 直列処理（合計3秒かかる）
async function fetchSequential() {
  const user    = await getUserData(1);      // 1秒待つ
  const orders  = await getOrders(user.id);  // さらに1秒待つ
  const product = await getProduct(101);     // さらに1秒待つ
}

// ✅ 並列処理（依存関係がないものは同時に実行）
async function fetchParallel() {
  const user = await getUserData(1);

  // 注文と商品は同時に取得できる場合
  const [orders, relatedProducts] = await Promise.all([
    getOrders(user.id),
    getProduct(101),
  ]);

  console.log('並列取得完了:', { orders, relatedProducts });
}
```

---

## エラーハンドリングのパターン

```javascript
// パターン1: try/catch（基本）
async function pattern1() {
  try {
    const data = await fetchData();
    return data;
  } catch (err) {
    console.error(err);
  }
}

// パターン2: エラーを戻り値として返す（例外を投げない設計）
async function pattern2() {
  const [err, data] = await fetchData()
    .then(data => [null, data])
    .catch(err  => [err, null]);

  if (err) {
    console.error('失敗:', err);
    return;
  }
  console.log('成功:', data);
}

// パターン3: ユーティリティ関数で共通化
const to = (promise) =>
  promise.then(data => [null, data]).catch(err => [err, null]);

async function pattern3() {
  const [err, user] = await to(getUserData(1));
  if (err) return console.error(err);

  const [err2, orders] = await to(getOrders(user.id));
  if (err2) return console.error(err2);

  console.log(user, orders);
}
```

---

## まとめ

| 比較項目 | コールバック | async/await |
|----------|-------------|-------------|
| 可読性 | ❌ ネストが深い | ✅ 同期処理のように読める |
| エラー処理 | ❌ 各階層で必要 | ✅ try/catch で一元管理 |
| デバッグ | ❌ スタックトレースが複雑 | ✅ 追いやすい |
| 並列処理 | △ 複雑になりがち | ✅ Promise.all で簡潔 |

> 💡 **既存のコールバック関数は `new Promise()` でラップ**してから async/await を使いましょう！

# コールバック地獄を async/await にリファクタリング

## Before: コールバック地獄の例

```javascript
// ユーザー情報を取得し、注文履歴を取得し、商品詳細を取得する処理
function getUserOrderDetails(userId) {
  getUser(userId, function(err, user) {
    if (err) {
      console.error('ユーザー取得エラー:', err);
      return;
    }

    getOrders(user.id, function(err, orders) {
      if (err) {
        console.error('注文取得エラー:', err);
        return;
      }

      getOrderItems(orders[0].id, function(err, items) {
        if (err) {
          console.error('商品取得エラー:', err);
          return;
        }

        getProductDetails(items[0].productId, function(err, product) {
          if (err) {
            console.error('商品詳細取得エラー:', err);
            return;
          }

          // ようやく処理完了...
          console.log('商品詳細:', product);
          updateInventory(product.id, items[0].quantity, function(err, result) {
            if (err) {
              console.error('在庫更新エラー:', err);
              return;
            }
            console.log('在庫更新完了:', result);
          });
        });
      });
    });
  });
}
```

---

## After: async/await でリファクタリング

```javascript
// async/await + エラーハンドリング込みのリファクタリング
async function getUserOrderDetails(userId) {
  try {
    const user         = await getUser(userId);
    const orders       = await getOrders(user.id);
    const items        = await getOrderItems(orders[0].id);
    const product      = await getProductDetails(items[0].productId);

    console.log('商品詳細:', product);

    const result       = await updateInventory(product.id, items[0].quantity);
    console.log('在庫更新完了:', result);

    return result;

  } catch (err) {
    // エラーを一箇所でまとめて処理
    console.error('処理中にエラーが発生しました:', err);
    throw err; // 必要に応じて再スロー
  }
}

// 呼び出し側
getUserOrderDetails(123)
  .then(result => console.log('完了:', result))
  .catch(err   => console.error('最終エラー:', err));

// または top-level await (ES2022+)
// const result = await getUserOrderDetails(123);
```

---

## コールバック関数を Promise に変換する方法

既存のコールバック関数が Promise に対応していない場合:

```javascript
// ❌ コールバック形式の関数
function getUser(id, callback) {
  db.query(`SELECT * FROM users WHERE id = ?`, [id], callback);
}

// ✅ パターン①: 手動で Promise でラップ
function getUser(id) {
  return new Promise((resolve, reject) => {
    db.query(`SELECT * FROM users WHERE id = ?`, [id], (err, result) => {
      if (err) reject(err);
      else     resolve(result);
    });
  });
}

// ✅ パターン②: util.promisify を使う (Node.js 標準)
const { promisify } = require('util');
const getUser = promisify(originalGetUser);

// ✅ パターン③: Promise.all で並列実行 (依存関係がない場合は高速化)
async function getParallelData(userId) {
  const [user, settings] = await Promise.all([
    getUser(userId),
    getSettings(userId), // 同時に実行される
  ]);
  return { user, settings };
}
```

---

## 比較まとめ

| 観点 | コールバック | async/await |
|------|------------|-------------|
| **可読性** | ❌ ネストが深くなる | ✅ 同期コードのように読める |
| **エラー処理** | ❌ 各段階で `if (err)` | ✅ `try/catch` で一元管理 |
| **デバッグ** | ❌ スタックトレースが追いにくい | ✅ 追いやすい |
| **並列処理** | 複雑 | ✅ `Promise.all` で簡潔 |

> 💡 **ポイント**: 直列処理は `await` を使い、並列処理は `Promise.all` を使うと効率的です。

