    const user    = await getUserAsync(userId);
    const orders  = await getOrdersAsync(user.id);
    const product = await getProductAsync(orders[0].productId);
    const stock   = await checkStockAsync(product.id);

    console.log('ユーザー:', user.name);
    console.log('注文:',     orders[0].id);
    console.log('商品:',     product.name);
    console.log('在庫:',     stock.quantity);

    return { user, orders, product, stock };

  } catch (err) {
    // エラーハンドリングが一箇所にまとまる！
    console.error('処理中にエラーが発生しました:', err);
    throw err;
  }
}

// 呼び出し
getUserOrderDetails('user_123');
```

---

## ⚡ 並列処理できる場合は Promise.all を活用

```javascript
async function getUserOrderDetails(userId) {
  try {
    const user = await getUserAsync(userId);

    // 注文と関連データを並列取得（独立している場合）
    const [orders, userProfile] = await Promise.all([
      getOrdersAsync(user.id),
      getProfileAsync(user.id),  // 並列実行でパフォーマンスUP！
    ]);

    const product = await getProductAsync(orders[0].productId);
    const stock   = await checkStockAsync(product.id);

    return { user, orders, userProfile, product, stock };

  } catch (err) {
    console.error('エラー:', err);
    throw err;
  }
}
```

---

## 📊 比較まとめ

| 項目 | コールバック地獄 | async/await |
|------|--------------|-------------|
| **可読性** | ❌ ネストが深く読みにくい | ✅ 同期処理のように読める |
| **エラー処理** | ❌ 各コールバックで個別対応 | ✅ try/catch で一元管理 |
| **デバッグ** | ❌ スタックトレースが追いにくい | ✅ 追いやすい |
| **並列処理** | △ 複雑になりがち | ✅ Promise.all で簡潔 |
| **テスト** | ❌ 書きにくい | ✅ 書きやすい |

---

## 💡 ポイントまとめ

```
1. コールバック関数 → Promise に変換（promisify or 手動ラップ）
2. function → async function に変更
3. コールバックの処理 → await に置き換え
4. 各所のエラー処理 → try/catch に集約
5. 独立した非同期処理 → Promise.all で並列化
```

