// App.tsx
import React, { useState } from 'react';
import ErrorBoundary from './ErrorBoundary';
import ErrorFallback from './ErrorFallback';
import withErrorBoundary from './withErrorBoundary';

// ❌ エラーを発生させるコンポーネント（テスト用）
const BuggyComponent = ({ shouldThrow }: { shouldThrow: boolean }) => {
  if (shouldThrow) {
    throw new Error('テスト用のエラーです！');
  }
  return <p>✅ 正常に動作しています</p>;
};

// HOC パターンで使用
const SafeComponent = withErrorBoundary(
  BuggyComponent,
  <p>HOC でラップされたフォールバック</p>
);

// ログ送信の例（Sentry など）
const handleError = (error: Error, errorInfo: React.ErrorInfo) => {
  // Sentry.captureException(error, { extra: errorInfo });
  console.log('ログ送信:', error.message);
};

const App = () => {
  const [shouldThrow, setShouldThrow] = useState(false);

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Error Boundary デモ</h1>

      {/* パターン1: デフォルトUIを使用 */}
      <ErrorBoundary onError={handleError}>
        <BuggyComponent shouldThrow={shouldThrow} />
      </ErrorBoundary>

      {/* パターン2: カスタムfallbackを指定 */}
      <ErrorBoundary
        fallback={<ErrorFallback error={null} resetError={() => {}} />}
        onError={handleError}
      >
        <BuggyComponent shouldThrow={shouldThrow} />
      </ErrorBoundary>

      {/* パターン3: HOCを使用 */}
      <SafeComponent shouldThrow={shouldThrow} />

      <button onClick={() => setShouldThrow((prev) => !prev)}>
        {shouldThrow ? '✅ エラーを解除' : '❌ エラーを発生させる'}
      </button>
    </div>
  );
};

export default App;
