| コンポーネント単位でのラップ | エラーの影響範囲を局所化できる |

> ⚠️ **注意**: Error Boundary はイベントハンドラ・非同期処理・SSR のエラーはキャッチしません。非同期エラーには `useErrorBoundary` フックを使って明示的に伝播させましょう。

# React Error Boundary の実装

## 1. 基本的な Error Boundary コンポーネント

```tsx
// components/ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  // エラーが発生したときに state を更新する
  static getDerivedStateFromError(error: Error): Partial<State> {
    return {
      hasError: true,
      error,
    };
  }

  // エラーのログを記録する
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.props.onError?.(error, errorInfo);
    this.setState({ errorInfo });
  }

  // エラー状態をリセットする
  handleReset = (): void => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  render(): ReactNode {
    const { hasError, error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (hasError) {
      // カスタム fallback が指定されている場合はそれを表示
      if (fallback) return fallback;

      // デフォルトのエラー表示
      return (
        <div style={styles.container}>
          <div style={styles.card}>
            <h2 style={styles.title}>⚠️ エラーが発生しました</h2>
            <p style={styles.message}>{error?.message}</p>
            {process.env.NODE_ENV === 'development' && (
              <details style={styles.details}>
                <summary style={styles.summary}>スタックトレース</summary>
                <pre style={styles.stack}>
                  {error?.stack}
                  {errorInfo?.componentStack}
                </pre>
              </details>
            )}
            <button style={styles.button} onClick={this.handleReset}>
              再試行する
            </button>
          </div>
        </div>
      );
    }

    return children;
  }
}

// インラインスタイル
