    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError) {
      return this.props.fallback
        ? this.props.fallback(this.state.error, this.reset)
        : (
          <div>
            <p>エラー: {this.state.error?.message}</p>
            <button onClick={this.reset}>再試行</button>
          </div>
        );
    }
    return this.props.children;
  }
}

// 使用例
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>{error.message}</p>
      <button onClick={reset}>もう一度試す</button>
    </div>
  )}
>
  <SomeComponent />
</ErrorBoundary>
```

### ライブラリ使うなら

`react-error-boundary` — フック対応、軽量、実績あり。

```bash
npm install react-error-boundary
```

```jsx
import { ErrorBoundary } from 'react-error-boundary';

function ErrorFallback({ error, resetErrorBoundary }) {
  return (
    <div>
      <p>{error.message}</p>
      <button onClick={resetErrorBoundary}>再試行</button>
    </div>
  );
}

<ErrorBoundary FallbackComponent={ErrorFallback} onReset={() => { /* stateリセット */ }}>
  <SomeComponent />
</ErrorBoundary>
```

---

**注意点3つ：**
1. イベントハンドラ内エラーはキャッチ不可（`try/catch`使う）
2. 非同期エラー（`async/await`）もキャッチ不可
3. SSR環境では動作異なる

