# Node.jsアプリのメモリリーク調査方法

## 1. メモリリークの兆候を確認する

```javascript
// process.memoryUsage()で定期的にメモリを監視
setInterval(() => {
  const mem = process.memoryUsage();
  console.log({
    rss: `${Math.round(mem.rss / 1024 / 1024)} MB`,       // 実際のメモリ使用量
    heapTotal: `${Math.round(mem.heapTotal / 1024 / 1024)} MB`, // ヒープ確保量
    heapUsed: `${Math.round(mem.heapUsed / 1024 / 1024)} MB`,  // ヒープ使用量
    external: `${Math.round(mem.external / 1024 / 1024)} MB`,  // C++オブジェクト
  });
}, 5000);
```

---

## 2. よくあるメモリリークの原因と対策

### ❌ グローバル変数への蓄積
```javascript
// 悪い例
const cache = {};
app.get('/data', (req, res) => {
  cache[Date.now()] = largeData; // 無限に増加
});

// 良い例（LRUキャッシュを使う）
const LRU = require('lru-cache');
const cache = new LRU({ max: 500, ttl: 1000 * 60 * 5 });
```

### ❌ イベントリスナーの解除忘れ
```javascript
// 悪い例
function setupHandler() {
  emitter.on('data', (data) => {
    // リスナーが増え続ける
  });
}

// 良い例
function setupHandler() {
  const handler = (data) => { /* 処理 */ };
  emitter.on('data', handler);

  return () => emitter.off('data', handler); // クリーンアップ関数を返す
}

// リスナー数の警告を活用
emitter.setMaxListeners(20);
```

### ❌ Closureによる参照保持
```javascript
// 悪い例
function createClosure() {
  const largeArray = new Array(1000000).fill('data');
  return function() {
    // largeArrayを使わないのに参照が残る
    return 'result';
  };
}

// 良い例
function createClosure() {
  const largeArray = new Array(1000000).fill('data');
  const result = largeArray.length; // 必要な値だけ取り出す
  // largeArrayはGCされる
  return function() {
    return result;
  };
}
```

### ❌ タイマーのクリア忘れ
```javascript
// 悪い例
class MyService {
  start() {
    this.timer = setInterval(() => this.doWork(), 1000);
  }
  // stopがないとtimerが残り続ける
}

// 良い例
class MyService {
  start() {
    this.timer = setInterval(() => this.doWork(), 1000);
  }
  stop() {
    clearInterval(this.timer);
    this.timer = null;
  }
}
```

---

## 3. Chrome DevToolsで調査する

```bash
# デバッグモードで起動
node --inspect app.js

# または既存プロセスにアタッチ
node --inspect=0.0.0.0:9229 app.js
```

```
Chrome で chrome://inspect を開く
  ↓
「inspect」をクリック
  ↓
「Memory」タブ → Heap Snapshot を取得
  ↓
しばらく負荷をかけた後、再度スナップショット取得
  ↓
「Comparison」で差分を確認 → 増えているオブジェクトを特定
```

---

## 4. ヒープダンプを分析する

```bash
npm install heapdump
```

```javascript
const heapdump = require('heapdump');

// メモリ急増時に自動でダンプ
let lastHeapUsed = 0;
setInterval(() => {
  const { heapUsed } = process.memoryUsage();
  const diff = heapUsed - lastHeapUsed;

  // 50MB以上増加したらダンプ
  if (diff > 50 * 1024 * 1024) {
    const filename = `heap-${Date.now()}.heapsnapshot`;
    heapdump.writeSnapshot(filename);
    console.log(`Heap dump written: ${filename}`);
  }
  lastHeapUsed = heapUsed;
}, 10000);

// シグナルで手動ダンプ
process.on('SIGUSR2', () => {
  heapdump.writeSnapshot(`heap-${Date.now()}.heapsnapshot`);
});
```

---

## 5. clinic.jsで可視化する（おすすめ）

```bash
npm install -g clinic

# メモリ問題の調査
clinic heapprofiler -- node app.js

# 全体的なパフォーマンス診断
clinic doctor -- node app.js

# 炎グラフでCPUボトルネック確認
clinic flame -- node app.js
```

---

## 6. 負荷テストと組み合わせる

```bash
# autocannon で負荷をかけながら監視
npm install -g autocannon

autocannon -c 100 -d 60 http://localhost:3000/api
```

```javascript
// 負荷テスト中のメモリ推移を記録
const fs = require('fs');
const log = fs.createWriteStream('memory.log');

setInterval(() => {
  const { heapUsed, rss } = process.memoryUsage();
  log.write(`${Date.now()},${heapUsed},${rss}\n`);
}, 1000);
```

---

## 7. 調査の進め方フロー

```
1. モニタリングで増加を確認
       ↓
2. 負荷テストで再現
       ↓
3. Heap Snapshotを比較（Before/After）
       ↓
4. 増加しているオブジェクトの型を特定
       ↓
5. コード内で該当オブジェクトを生成している箇所を探す
       ↓
6. 修正 → 再テストで確認
```

---

## まとめ

| ツール | 用途 |
|--------|------|
| `process.memoryUsage()` | 簡易モニタリング |
| Chrome DevTools | ヒープスナップショット比較 |
| `heapdump` | 本番環境でのダンプ取得 |
| `clinic.js` | 総合的な可視化・診断 |
| `autocannon` | 負荷テストで問題再現 |

**まずは`--inspect`でDevToolsを使ったヒープスナップショット比較が最も手軽で効果的です。**

# Node.jsアプリのメモリリーク調査方法

## 🔍 メモリリークの兆候

```
- アプリのメモリ使用量が時間とともに増加し続ける
- GC（ガベージコレクション）後もメモリが解放されない
- アプリが徐々に遅くなる、またはクラッシュする
```

---

## 📊 Step 1: メモリ使用量の監視

### process.memoryUsage() で基本確認

```javascript
// memory-monitor.js
setInterval(() => {
  const usage = process.memoryUsage();
  console.log({
    rss:       `${Math.round(usage.rss / 1024 / 1024)} MB`,       // 実際のメモリ使用量
    heapTotal: `${Math.round(usage.heapTotal / 1024 / 1024)} MB`, // V8が確保したヒープ
    heapUsed:  `${Math.round(usage.heapUsed / 1024 / 1024)} MB`,  // 実際に使用中のヒープ
    external:  `${Math.round(usage.external / 1024 / 1024)} MB`,  // C++オブジェクト
  });
}, 5000);
```

### 増加傾向の検出

```javascript
class MemoryLeakDetector {
  constructor(threshold = 50) {
    this.threshold = threshold; // MB
    this.baseline = null;
  }

  start() {
    this.baseline = process.memoryUsage().heapUsed;

    setInterval(() => {
      const current = process.memoryUsage().heapUsed;
      const diff = (current - this.baseline) / 1024 / 1024;

      if (diff > this.threshold) {
        console.warn(`⚠️  メモリ増加検出: +${diff.toFixed(2)} MB`);
      }
    }, 10000);
  }
}

new MemoryLeakDetector(50).start();
```

---

## 🛠️ Step 2: ヒープスナップショットの取得

### --inspect フラグで Chrome DevTools を使用

```bash
# デバッグモードで起動
node --inspect app.js

# または既存プロセスにアタッチ
node --inspect=0.0.0.0:9229 app.js
```

```
1. Chrome で chrome://inspect を開く
2. 対象プロセスの「inspect」をクリック
3. Memory タブ → Heap snapshot を取得
4. 時間をおいてもう一度取得
5. 「Comparison」モードで差分を確認
```

### コードからスナップショットを取得

```javascript
const v8 = require('v8');
const fs = require('fs');

function takeHeapSnapshot(filename) {
  const snapshotStream = v8.writeHeapSnapshot();
  console.log(`スナップショット保存: ${snapshotStream}`);
}

// 特定のタイミングで取得
process.on('SIGUSR2', () => {
  takeHeapSnapshot(`heap-${Date.now()}.heapsnapshot`);
});
```

```bash
# シグナルを送信してスナップショット取得
kill -USR2 <PID>
```

---

## 🔬 Step 3: heapdump / clinic.js の活用

### heapdump パッケージ

```bash
npm install heapdump
```

```javascript
const heapdump = require('heapdump');

// HTTPエンドポイントでスナップショット取得
app.get('/debug/heap', (req, res) => {
  heapdump.writeSnapshot(`./heap-${Date.now()}.heapsnapshot`, (err, filename) => {
    if (err) return res.status(500).send(err);
    res.send(`スナップショット作成: ${filename}`);
  });
});
```

### clinic.js（強力な診断ツール）

```bash
npm install -g clinic

# メモリ診断
clinic heapprofiler -- node app.js

# 全体的な診断
clinic doctor -- node app.js

# 炎グラフ（CPU）
clinic flame -- node app.js
```

---

## 🐛 Step 4: よくあるメモリリークパターンと対策

### ❌ パターン1: グローバル変数への蓄積

```javascript
// 悪い例
const cache = [];

app.get('/data', (req, res) => {
  cache.push(req.query); // 永遠に蓄積され続ける
  res.json(cache);
});

// 良い例（LRUキャッシュを使用）
const LRU = require('lru-cache');
const cache = new LRU({ max: 500, ttl: 1000 * 60 * 10 }); // 最大500件、10分TTL
```

### ❌ パターン2: イベントリスナーの解除忘れ

```javascript
// 悪い例
function setupListener(emitter) {
  emitter.on('data', (data) => {
    // リスナーが増え続ける
  });
}

// 良い例
function setupListener(emitter) {
  const handler = (data) => { /* 処理 */ };
  emitter.on('data', handler);

  // クリーンアップ関数を返す
  return () => emitter.off('data', handler);
}

// 最大リスナー数の警告を活用
emitter.setMaxListeners(10);
```

### ❌ パターン3: クロージャによるメモリ保持

```javascript
// 悪い例
function createHandler() {
  const largeData = new Array(1000000).fill('data'); // 大量データ

  return function handler(req, res) {
    // largeData が解放されない
    res.send('ok');
  };
}

// 良い例
function createHandler() {
  // 必要なものだけ保持
  const config = { limit: 100 };

  return function handler(req, res) {
    res.send('ok');
  };
}
```

### ❌ パターン4: タイマーのクリア忘れ

```javascript
// 悪い例
class Service {
  start() {
    this.timer = setInterval(() => {
      this.process();
    }, 1000);
  }
  // stop() がない！
}

// 良い例
class Service {
  start() {
    this.timer = setInterval(() => {
      this.process();
    }, 1000);
  }

  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}
```

### ❌ パターン5: Promise / async の未処理

```javascript
// 悪い例
const pendingRequests = new Map();

async function makeRequest(id) {
  const promise = fetch(`/api/${id}`);
  pendingRequests.set(id, promise); // 完了後も残る
  return await promise;
}

// 良い例
async function makeRequest(id) {
  const promise = fetch(`/api/${id}`);
  pendingRequests.set(id, promise);

  try {
    return await promise;
  } finally {
    pendingRequests.delete(id); // 必ず削除
  }
}
```

---

## 📈 Step 5: 本番環境での監視

### pm2 でのメモリ監視

```bash
# メモリ超過時に自動再起動
pm2 start app.js --max-memory-restart 500M

# 監視
pm2 monit
```

### カスタム監視 + アラート

```javascript
const os = require('os');

class ProductionMemoryMonitor {
  constructor(options = {}) {
    this.maxHeapMB = options.maxHeapMB || 512;
    this.alertCallback = options.onAlert || console.error;
    this.samples = [];
  }

  start() {
    setInterval(() => {
      const usage = process.memoryUsage();
      const heapMB = usage.heapUsed / 1024 / 1024;

      this.samples.push({ time: Date.now(), heap: heapMB });

      // 直近10サンプルを保持
      if (this.samples.length > 10) this.samples.shift();

      // 閾値チェック
      if (heapMB > this.maxHeapMB) {
        this.alertCallback({
          message: 'メモリ使用量が閾値を超えました',
          current: `${heapMB.toFixed(2)} MB`,
          threshold: `${this.maxHeapMB} MB`,
          trend: this.getTrend(),
        });
      }
    }, 30000);
  }

  getTrend() {
    if (this.samples.length < 2) return 'unknown';
    const first = this.samples[0].heap;
    const last = this.samples[this.samples.length - 1].heap;
    return last > first ? '📈 増加中' : '📉 安定';
  }
}
```

---

## 🔧 便利なツールまとめ

| ツール | 用途 | 場面 |
|--------|------|------|
| `Chrome DevTools` | ヒープスナップショット分析 | 開発時 |
| `clinic.js` | 総合的なパフォーマンス診断 | 開発・ステージング |
| `heapdump` | スナップショット自動取得 | 本番調査 |
| `pm2` | メモリ監視・自動再起動 | 本番運用 |
| `Datadog/New Relic` | 継続的なメモリ監視 | 本番監視 |

---

## ✅ 調査の進め方まとめ

```
1. process.memoryUsage() でメモリ増加を確認
        ↓
2. 再現できる最小ケースを作成
        ↓
3. ヒープスナップショットを「前」「後」で比較
        ↓
4. 増加しているオブジェクトを特定
        ↓
5. コードでそのオブジェクトの生成箇所を追跡
        ↓
6. 適切にクリーンアップ処理を追加
```

メモリリークの原因特定には**ヒープスナップショットの比較**が最も効果的です。まず `--inspect` フラグで Chrome DevTools を使った分析から始めることをおすすめします。

# Node.jsアプリのメモリリーク調査方法

## 🔍 メモリリークの兆候

```
- プロセスのメモリ使用量が徐々に増加し続ける
- 長時間稼働後にアプリが遅くなる・クラッシュする
- GC（ガベージコレクション）が頻繁に実行される
```

---

## 📊 ステップ1: メモリ使用量の監視

### process.memoryUsage() で基本確認

```javascript
// memory-monitor.js
setInterval(() => {
  const mem = process.memoryUsage();
  console.log({
    rss:      `${Math.round(mem.rss / 1024 / 1024)} MB`,      // 実メモリ使用量
    heapTotal:`${Math.round(mem.heapTotal / 1024 / 1024)} MB`, // ヒープ確保量
    heapUsed: `${Math.round(mem.heapUsed / 1024 / 1024)} MB`,  // ヒープ使用量
    external: `${Math.round(mem.external / 1024 / 1024)} MB`,  // C++オブジェクト
  });
}, 5000);
```

### clinic.js で可視化（おすすめ）

```bash
# インストール
npm install -g clinic

# 計測
clinic doctor -- node app.js
clinic heapprofiler -- node app.js
clinic flame -- node app.js
```

---

## 🛠 ステップ2: ヒープスナップショットの取得

### 方法A: Chrome DevTools を使う

```bash
# インスペクターモードで起動
node --inspect app.js

# または既存プロセスにアタッチ
node --inspect=0.0.0.0:9229 app.js
```

```
1. Chrome で chrome://inspect を開く
2. 対象プロセスの「inspect」をクリック
3. Memory タブ → Heap snapshot
4. 時間をおいて複数回スナップショット取得
5. スナップショットを比較して増加オブジェクトを特定
```

### 方法B: コードからスナップショット取得

```javascript
const v8 = require('v8');
const fs = require('fs');

// ヒープスナップショットをファイルに保存
function takeHeapSnapshot(filename) {
  const snapshotStream = v8.writeHeapSnapshot();
  console.log(`Snapshot written to: ${snapshotStream}`);
}

// APIエンドポイントとして公開する例
app.get('/debug/heap-snapshot', (req, res) => {
  const filename = `heap-${Date.now()}.heapsnapshot`;
  const snapshotStream = v8.writeHeapSnapshot(filename);
  res.json({ file: snapshotStream });
});
```

---

## 📦 ステップ3: heapdump / memwatch-next を使う

```bash
npm install heapdump
npm install @airbnb/node-memwatch
```

```javascript
const memwatch = require('@airbnb/node-memwatch');
const heapdump = require('heapdump');

// メモリリーク検出時に自動でスナップショット
memwatch.on('leak', (info) => {
  console.error('🚨 Memory leak detected:', info);
  // growth: メモリ増加量
  // reason: リーク理由

  const filename = `leak-${Date.now()}.heapsnapshot`;
  heapdump.writeSnapshot(filename, (err, filename) => {
    if (!err) console.log('Snapshot:', filename);
  });
});

// GC統計情報
memwatch.on('stats', (stats) => {
  console.log('GC stats:', stats);
});
```

---

## 🔬 ステップ4: よくあるリークパターンと対策

### ❌ パターン1: イベントリスナーの解放漏れ

```javascript
// 悪い例
class MyService {
  constructor(emitter) {
    // リクエストごとに追加され続ける
    emitter.on('data', this.handleData.bind(this));
  }
}

// 良い例
class MyService {
  constructor(emitter) {
    this.handler = this.handleData.bind(this);
    emitter.on('data', this.handler);
  }

  destroy(emitter) {
    emitter.off('data', this.handler); // 必ず解放
  }
}

// リスナー数の上限警告を活用
emitter.setMaxListeners(20);
```

### ❌ パターン2: クロージャによるリーク

```javascript
// 悪い例 - largeData がずっとメモリに残る
function createLeak() {
  const largeData = new Array(1000000).fill('data');

  return function() {
    // largeData を使わないのに参照が残る
    console.log('called');
  };
}

// 良い例
function noLeak() {
  const largeData = new Array(1000000).fill('data');
  const result = processData(largeData);
  // largeData への参照を切る

  return function() {
    console.log('result:', result); // 必要なデータのみ保持
  };
}
```

### ❌ パターン3: グローバルキャッシュの肥大化

```javascript
// 悪い例 - 無制限に増加
const cache = {};
app.get('/data/:id', (req, res) => {
  cache[req.params.id] = fetchData(req.params.id);
  res.json(cache[req.params.id]);
});

// 良い例 - LRUキャッシュで上限設定
const LRU = require('lru-cache');
const cache = new LRU({
  max: 500,          // 最大500件
  ttl: 1000 * 60 * 5 // 5分でexpire
});
```

### ❌ パターン4: タイマーの解放漏れ

```javascript
// 悪い例
class PollingService {
  start() {
    setInterval(() => this.poll(), 1000); // intervalIdを保持しない
  }
}

// 良い例
class PollingService {
  start() {
    this.intervalId = setInterval(() => this.poll(), 1000);
  }

  stop() {
    clearInterval(this.intervalId); // 必ず停止
  }
}
```

### ❌ パターン5: Promiseチェーンのリーク

```javascript
// 悪い例 - 解決されないPromiseが蓄積
const pendingPromises = [];

function addPromise() {
  const p = new Promise((resolve) => {
    // resolve が呼ばれない場合がある
  });
  pendingPromises.push(p);
}

// 良い例 - タイムアウトを設定
function withTimeout(promise, ms = 5000) {
  const timeout = new Promise((_, reject) =>
    setTimeout(() => reject(new Error('Timeout')), ms)
  );
  return Promise.race([promise, timeout]);
}
```

---

## 📈 ステップ5: 本番環境での監視

```javascript
// prometheus + prom-client での監視
const client = require('prom-client');

const heapUsed = new client.Gauge({
  name: 'nodejs_heap_used_bytes',
  help: 'Node.js heap used',
});

setInterval(() => {
  heapUsed.set(process.memoryUsage().heapUsed);
}, 10000);
```

```yaml
# docker-compose での設定例
services:
  app:
    environment:
      - NODE_OPTIONS=--max-old-space-size=512  # ヒープ上限設定
```

---

## 🚀 調査フロー まとめ

```
1. 監視ツールでメモリ増加を確認
       ↓
2. 負荷テスト中にヒープスナップショットを複数取得
       ↓
3. Chrome DevTools でスナップショットを比較
   「増加しているオブジェクト」を特定
       ↓
4. コードでリークパターンを探す
       ↓
5. 修正 → 再テストで確認
```

---

## 🧰 便利ツール一覧

| ツール | 用途 |
|--------|------|
| `clinic.js` | オールインワン診断 |
| `Chrome DevTools` | ヒープ分析 |
| `memwatch-next` | リーク自動検出 |
| `autocannon` | 負荷テスト |
| `0x` | フレームグラフ生成 |
| `leakage` | テスト用リーク検出 |

何か特定のシナリオや詳細な手順について知りたい場合はお気軽にどうぞ！

